INSERT INTO public.partners (id, name, slug, description, excerpt, logo, country, highlights, "order", active, "createdAt", "updatedAt", image, websites) VALUES ('e5f30671-4f84-4d49-ad81-c191b174391a', 'Lipoid', 'lipoid', 'Fundada em 1977, a Lipoid é a maior fornecedora independente de lecitinas e fosfolipídeos de alta pureza do mundo, com sede em Ludwigshafen, na Alemanha. O grupo Lipoid é hoje o único fornecedor a produzir todo o espectro de fosfolipídeos naturais, hidrogenados e sinteticamente puros, para aplicações farmacêuticas, cosméticas e alimentícias.
INSERT INTO public.partners (id, name, slug, description, excerpt, logo, country, highlights, "order", active, "createdAt", "updatedAt", image, websites) VALUES ('c60dce15-e6a7-4eba-a91a-a0d2a79733b4', 'Readline Biotech', 'readline-biotech', 'A Readline Biotech (Shenzhen Readline Biotech Co., Ltd.) é uma biotech chinesa sediada em Shenzhen, com unidades adicionais em Zhuhai e Gansu, dedicada a ativos biotecnológicos "verdes" — aminoácidos, peptídeos, proteínas, açúcares, ácidos nucleicos, lipídeos e produtos naturais.
