INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('5ed48aed-6956-4ebc-b84b-15b70ada417f', 'Lipoid E PC S', 'lipoid-e-pc-s', 'Lipoid E PC S integra a família “Egg Lecithins and Phospholipids”. Sua identidade técnica é fosfatidilcolina de gema de ovo com teor mínimo de 96%. Essa definição permite selecionar a matéria- prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('015b7f9b-5d44-4886-b58b-b036246393bf', 'LIPOID E PE', 'lipoid-e-pe', 'LIPOID E PE integra a família “Egg Lecithins and Phospholipids”. Sua identidade técnica é fosfatidiletanolamina de gema de ovo com teor mínimo de 97%. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('059b1779-fb86-4754-851a-b36cf874d906', 'Lipoid E PG', 'lipoid-e-pg', 'Lipoid E PG integra a família “Egg Lecithins and Phospholipids”. Sua identidade técnica é fosfatidilglicerol de gema de ovo, sal de sódio, com teor mínimo de 98%. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('633c28f7-9f77-4ce7-a354-5c49be6292d4', 'Phosal 50 S.A.+', 'phosal-50-sa', 'Phosal 50 S.A.+ integra a família “Soybean Lecithins and Phospholipid Systems”. Sua identidade técnica é formulação de fosfatidilcolina com teor mínimo de 50% em óleo de cártamo. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('d012b079-a704-4127-8fdf-9d8032994090', 'ReGrow-Ex', 'regrow-ex', 'ReGrow-Ex é o Biotinoyl Tripeptide-1 da READLINE, um tripeptídeo formado pela associação de biotina com a sequência GHK. O ativo foi desenvolvido para cuidados capilares e para formulações destinadas a cílios e sobrancelhas, com foco no suporte ao folículo e à estrutura do fio.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('32c211de-0ac2-4817-87df-10a963cbf9b0', 'Phosal 35 SB', 'phosal-35-sb', 'Phosal 35 SB pertence à linha PHOSAL de concentrados líquidos e isentos de água à base de fosfolipídios. A planilha informa o nome e o código comercial, mas não detalha a composição quantitativa ou o veículo desta apresentação; esses dados devem ser obtidos na ficha técnica vigente.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('610b92ce-cfda-4acd-81fe-5cc8e502a4b1', 'Phosal H 50', 'phosal-h-50', 'Phosal H 50 integra a família “Phospholipid Systems”. Sua identidade técnica é fosfatidilcolina de girassol em óleo de girassol, com teor mínimo de 50%. Essa definição permite selecionar a matéria- prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('005d7d86-3b03-4e8d-aa44-406663f3c24c', 'Phosal 53 MCT', 'phosal-53-mct', 'Phosal 53 MCT integra a família “Phospholipid Systems”. Sua identidade técnica é fosfatidilcolina em triglicerídeos de cadeia média, com teor mínimo de 53%. Essa definição permite selecionar a matéria- prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('1fbf6f66-30ab-4149-90d0-41d5b56b272e', 'Phosal 50 PG', 'phosal-50-pg', 'Phosal 50 PG integra a família “Phospholipid Systems”. Sua identidade técnica é fosfatidilcolina em propilenoglicol, com teor mínimo de 50%. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('7291ffba-6444-4975-a9b7-3d41d842ef42', 'Phosal P 50', 'phosal-p-50', 'Phosal P 50 integra a família “Phospholipid Systems”. Sua identidade técnica é fosfatidilcolina de soja não transgênica em triglicerídeos de cadeia média. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('16b0bf63-66f1-4596-8d16-22c935f1d8f8', 'Phosal Curcumin', 'phosal-curcumin', 'Phosal Curcumin integra a família “Phospholipid Systems”. Sua identidade técnica é sistema com fosfatidilcolina em MCT e 7% de curcumina. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('c3225a16-e952-4290-bc79-8f138349fe38', 'D-Panthenol', 'd-panthenol', 'D-Panthenol, também denominado dexpanthenol, é a forma dextrógira do panthenol, um análogo alcoólico do ácido pantotênico (vitamina B5). Em sistemas biológicos, pode ser convertido em ácido pantotênico, componente relacionado ao metabolismo da coenzima A. No desenvolvimento cosmético, é empregado como agente condicionante para pele e cabelos, umectante e componente de suporte à hidratação.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('0145c4fb-cc52-4af9-9100-032bf93b98b1', 'Phospholipon 90G', 'phospholipon-90g', 'Phospholipon 90G integra a família “Soybean Phospholipids”. Sua identidade técnica é fosfatidilcolina de soja com teor mínimo de 94%, em forma granulada. Essa definição permite selecionar a matéria- prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('406e4d52-807e-4752-a365-cbf66277d6f3', 'Lipoid H 100', 'lipoid-h-100', 'Lipoid H 100 integra a família “Sunflower Phospholipids”. Sua identidade técnica é fosfatidilcolina de girassol não transgênico com teor mínimo de 94%. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('7c2d2513-ad51-4a2a-a43c-9584b0d7c8f8', 'Lipoid S 75', 'lipoid-s-75', 'Lipoid S 75 integra a família “Soybean Phospholipids”. Sua identidade técnica é fosfolipídios de soja com aproximadamente 70% de fosfatidilcolina. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('0185ed9f-88d4-40c8-8eca-763453585676', 'Lipoid S 100', 'lipoid-s-100', 'Lipoid S 100 integra a família “Soybean Phospholipids”. Sua identidade técnica é fosfatidilcolina de soja com teor mínimo de 94%. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('ea16233d-4cd4-40e0-9405-8eb542af8d1b', 'Phospholipon 80H', 'phospholipon-80h', 'Phospholipon 80H integra a família “Hydrogenated Soybean Phospholipids”. Sua identidade técnica é fosfolipídios de soja hidrogenados com cerca de 70% de fosfatidilcolina. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('1f89f62d-6df9-4d76-b654-b7f1606eae75', 'Phospholipon 90H', 'phospholipon-90h', 'Phospholipon 90H integra a família “Hydrogenated Soybean Phospholipids”. Sua identidade técnica é fosfolipídios de soja hidrogenados com teor mínimo de 90%. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('e7fd0952-f5d7-4a92-96fe-bbe250914bf4', 'Lipoid S PC-3', 'lipoid-s-pc-3', 'Lipoid S PC-3 integra a família “Hydrogenated Soybean Phospholipids”. Sua identidade técnica é fosfatidilcolina de soja hidrogenada com teor mínimo de 98%. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('ab5a005f-322d-4846-acfa-1a5d4f795a9b', 'Lipoid P 45', 'lipoid-p-45', 'Lipoid P 45 integra a família “Non-GMO Soybean Phospholipids”. Sua identidade técnica é fração de lecitina de soja não transgênica com no mínimo 45% de fosfatidilcolina. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('e8634387-e980-45d1-bdca-9cd926c7d4ff', 'Lipoid P 75', 'lipoid-p-75', 'Lipoid P 75 integra a família “Non-GMO Soybean Phospholipids”. Sua identidade técnica é fosfolipídios de soja não transgênica com no mínimo 70% de fosfatidilcolina. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('7896e4bf-43ce-4684-b451-9286cdbbcf79', 'Sodium Oleate B', 'sodium-oleate-b', 'Sodium Oleate B integra a família “Fatty Acid Salts”. Sua identidade técnica é oleato de sódio de origem vegetal. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('2f31b664-c76e-426f-9ad2-3d585b82c3a7', 'Lipoid P 100', 'lipoid-p-100', 'Lipoid P 100 integra a família “Non-GMO Soybean Phospholipids”. Sua identidade técnica é fosfatidilcolina de soja não transgênica com teor mínimo de 90%. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('251ef683-6170-47c8-8fc9-f2e38133c7f0', 'Lipoid P 75-3', 'lipoid-p-75-3', 'Lipoid P 75-3 integra a família “Hydrogenated Non-GMO Soybean Phospholipids”. Sua identidade técnica é fosfolipídios de soja não transgênica hidrogenados, com cerca de 70% de fosfatidilcolina.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('655f94e6-5d47-4515-b29b-c48ae9d6cc28', 'Lipoid P 100-3', 'lipoid-p-100-3', 'Lipoid P 100-3 integra a família “Hydrogenated Non-GMO Soybean Phospholipids”. Sua identidade técnica é fosfatidilcolina de soja não transgênica hidrogenada, com teor mínimo de 90%. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('6d4761e8-f093-4a94-b9ec-df3307d19a85', 'WrinFix-Px', 'wrinfix-px', 'WrinFix-Px é o Hydroxypropyl Tetrahydropyrantriol da READLINE, um derivado de xilose desenvolvido para estratégias cosméticas de hidratação, firmeza, suavização da superfície cutânea e redução da aparência de rugas.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('ed8e58f7-f674-45e9-b103-17509d7a1b9a', 'WrinFix H8', 'wrinfix-h8', 'WrinFix H8 é o Acetyl Hexapeptide-8 da READLINE, um peptídeo desenvolvido para formulações cosméticas voltadas à aparência de linhas de expressão, especialmente em produtos faciais e para a região periocular.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('99487da9-c0d5-4c6c-bf29-bd534ef08ba5', 'Rice - Herbasol® Plant Water', 'rice-herbasol-plant-water', 'Rice - Herbasol® Plant Water é uma água vegetal obtida da matéria-prima indicada no nome comercial. A apresentação fornece uma base aquosa botânica para formulações em que leveza, transparência e identidade vegetal são requisitos do projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('f34c9dd2-6ab7-440f-a8ab-282ec37c2135', 'HydraFix-Pro', 'hydrafix-pro', 'HydraFix-Pro é a ectoína da READLINE, um derivado cíclico de aminoácido associado à adaptação de microrganismos halófilos a ambientes de alta salinidade. Em cosméticos, atua como ativo de hidratação e proteção biomolecular diante de fatores de estresse ambiental.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('a166769a-5d61-494a-bc76-ffca3446be0a', 'Lipoid H 85', 'lipoid-h-85', 'Lipoid H 85 integra a família “Sunflower Phospholipids”. Sua identidade técnica é fosfatidilcolina de girassol não transgênico com teor mínimo de 85%. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('5401121b-63bb-40b8-946d-cb2e7bd86a2d', 'Lipoid H 100-3', 'lipoid-h-100-3', 'Lipoid H 100-3 integra a família “Hydrogenated Sunflower Phospholipids”. Sua identidade técnica é fosfatidilcolina de girassol hidrogenada com teor mínimo de 94%. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('97f47ef0-f006-4b94-bf06-281ad2fc6830', 'Lipoid H 65', 'lipoid-h-65', 'Lipoid H 65 integra a família “Sunflower Phospholipids”. Sua identidade técnica é fosfolipídios de girassol com no mínimo 60% de fosfatidilcolina. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('cb4ddd40-3833-4ac4-83e1-ed0cd343b1a3', 'Lipoid GPC 85 F', 'lipoid-gpc-85-f', 'Lipoid GPC 85 F integra a família “Glycerophosphocholines”. Sua identidade técnica é concentrado fluido de sn-glicero-3-fosfocolina em água. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('800fd52d-573c-413f-84fe-93dc9fa67c35', 'Lipoid GPC', 'lipoid-gpc', 'Lipoid GPC integra a família “Glycerophosphocholines”. Sua identidade técnica é sn-Glicero-3- fosfocolina com teor mínimo de 98%. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('40d1bef1-15a6-449f-adc3-31a4f246d9d3', 'Lipoid MCT', 'lipoid-mct', 'Lipoid MCT integra a família “Purified Oils”. Sua identidade técnica é triglicerídeos de cadeia média de grau compendial. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('05e1cdd8-df51-478a-b5b9-ea7daa28879d', 'Lipoid Purified Fish Oil', 'lipoid-purified-fish-oil', 'Lipoid Purified Fish Oil integra a família “Purified Oils”. Sua identidade técnica é óleo de peixe purificado de grau compendial. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('c58e9257-9564-48cf-ab6c-f5cc29adba0d', 'Lipoid S 45', 'lipoid-s-45', 'Lipoid S 45 integra a família “Soybean Phospholipids”. Sua identidade técnica é fração de lecitina de soja com 45% de fosfatidilcolina. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('c46b29e2-f8e5-4848-bf89-0c75559672e4', 'Soybean Oil 700', 'soybean-oil-700', 'Soybean Oil 700 integra a família “Purified Oils”. Sua identidade técnica é óleo de soja do portfólio de óleos purificados. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('4fd02711-dbe3-4622-9611-78799ce32a2c', 'Soy Oil Herbamilk Eco', 'soy-oil-herbamilk-eco', 'Soy Oil Herbamilk Eco integra a família “Cosmetic Botanical-Phospholipid System”. Sua identidade técnica é leite cosmético vegetal com óleo de soja, fosfolipídios hidrogenados e matriz de glicerina.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('9e37dabb-1172-4c07-9464-b11a93dd582b', 'Lipoid P LPC 80', 'lipoid-p-lpc-80', 'Lipoid P LPC 80 integra a família “Lysophosphatidylcholine”. Sua identidade técnica é lisofosfatidilcolina com 80% e até 20% de fosfatidilcolina. Essa definição permite selecionar a matéria- prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('bb0bf9b4-0c1d-4fe4-9aae-5fa3b69d1272', 'Lipoid PC 14:0/14:0 (DMPC)', 'lipoid-pc-140140-dmpc', 'Lipoid PC 14:0/14:0 (DMPC) corresponde a 1,2-dimiristoil-sn-glicero-3-fosfocolina. Trata-se de um fosfolipídio do tipo fosfatidilcolina zwitteriônica, com composição molecular definida, característica que permite controlar de forma mais reprodutível a organização, a carga superficial e as propriedades da fase lipídica.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('4320ca35-e76d-451b-b752-904ab22af1be', 'LIPOID S LPC-3 RS', 'lipoid-s-lpc-3-rs', 'LIPOID S LPC-3 RS é um padrão de referência qualificado associado ao analito LIPOID S LPC-3. Sua finalidade é fornecer um material rastreável para métodos de identificação, teor, pureza e perfil de componentes em matérias-primas e produtos que contenham fosfolipídios.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('fb216c46-d4cb-4c05-81e8-28a217a63c1c', 'Lipoid Dotap-CI', 'lipoid-dotap-ci', 'Lipoid Dotap-CI integra a família “Cationic Lipids”. Sua identidade técnica é dOTAP cloreto, lipídio catiônico sintético. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('1caf97d6-31bc-47ac-8009-583cfb87cda4', 'Lipoid PC 16:0/16:0 (DPPC)', 'lipoid-pc-160160-dppc', 'Lipoid PC 16:0/16:0 (DPPC) corresponde a 1,2-dipalmitoil-sn-glicero-3-fosfocolina. Trata-se de um fosfolipídio do tipo fosfatidilcolina zwitteriônica, com composição molecular definida, característica que permite controlar de forma mais reprodutível a organização, a carga superficial e as propriedades da fase lipídica.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('3953736d-fd35-45f8-9f3e-a42fb204d92c', 'Lipoid PC 18:0/18:0 (DSPC)', 'lipoid-pc-180180-dspc', 'Lipoid PC 18:0/18:0 (DSPC) corresponde a 1,2-distearoil-sn-glicero-3-fosfocolina. Trata-se de um fosfolipídio do tipo fosfatidilcolina zwitteriônica, com composição molecular definida, característica que permite controlar de forma mais reprodutível a organização, a carga superficial e as propriedades da fase lipídica.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('73989e3f-fd13-437c-95d6-1da30e3e3ce9', 'LIPOID PC 18:1/18:1 (DOPC)', 'lipoid-pc-181181-dopc', 'LIPOID PC 18:1/18:1 (DOPC) corresponde a 1,2-dioleoil-sn-glicero-3-fosfocolina. Trata-se de um fosfolipídio do tipo fosfatidilcolina zwitteriônica, com composição molecular definida, característica que permite controlar de forma mais reprodutível a organização, a carga superficial e as propriedades da fase lipídica.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('868d136f-5f6d-46c0-89a1-9352b0f09ffa', 'Lipoid PC 16:0/18:1 (POPC)', 'lipoid-pc-160181-popc', 'Lipoid PC 16:0/18:1 (POPC) corresponde a 1-palmitoil-2-oleoil-sn-glicero-3-fosfocolina. Trata-se de um fosfolipídio do tipo fosfatidilcolina zwitteriônica, com composição molecular definida, característica que permite controlar de forma mais reprodutível a organização, a carga superficial e as propriedades da fase lipídica.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('599e3047-f956-4e18-bc4f-a035935f08b8', 'Lipoid PG 14:0/14:0 (DMPG-Na)', 'lipoid-pg-140140-dmpg-na', 'Lipoid PG 14:0/14:0 (DMPG-Na) corresponde a 1,2-dimiristoil-sn-glicero-3-fosfoglicerol, sal de sódio.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('a9a02368-8c9c-4491-b498-76f4bcd7af2d', 'Lipoid PG 16:0/16:0 (DPPG-Na)', 'lipoid-pg-160160-dppg-na', 'Lipoid PG 16:0/16:0 (DPPG-Na) corresponde a 1,2-dipalmitoil-sn-glicero-3-fosfoglicerol, sal de sódio.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('a86205b3-c423-40ef-bc18-13c92585240e', 'UltraHeal-Pro', 'ultraheal-pro', 'UltraHeal-Pro é o Copper Tripeptide-1 da READLINE, um complexo coordenado entre o tripeptídeo Gly- His-Lys (GHK) e um íon cobre. A coordenação metálica confere coloração azul ao material e exige atenção específica à compatibilidade durante o desenvolvimento da formulação.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('e44f6b9d-b8df-4683-b185-2db90580c59d', 'AntiGly-Ex', 'antigly-ex', 'AntiGly-Ex é o Decarboxy Carnosine HCl da READLINE, um pseudodipeptídeo composto por beta-alanina e histamina. Sua estrutura difere da carnosina e apresenta maior resistência à hidrólise por carnosinase, característica relevante para estratégias cosméticas antiglicação.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('75c6c2fb-f948-4e38-a453-2c833a3aac53', 'AntiOxd-Ex', 'antioxd-ex', 'AntiOxd-Ex é a ergothioneine da READLINE, um derivado de histidina contendo enxofre, reconhecido por sua capacidade de interagir com diferentes espécies reativas de oxigênio. Em projetos cosméticos, o ingrediente é utilizado como componente antioxidante para formulações voltadas à proteção da pele diante de radiação, poluição e outros fatores associados ao estresse oxidativo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('2c3dc148-0aa1-4dcf-b414-9b46078257d1', 'β-Nicotinamide Mononucleotide', 'beta-nicotinamide-mononucleotide', 'β-Nicotinamide Mononucleotide, ou β-NMN, é um nucleotídeo formado por nicotinamida, ribose e fosfato.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('9e388caf-dcc0-48ce-9602-5e93459adbc1', 'Ergothioneine', 'ergothioneine', 'Ergothioneine é um derivado de histidina contendo enxofre, produzido na natureza por determinados microrganismos. Sua química favorece a interação com espécies reativas e sustenta seu uso como antioxidante em formulações cosméticas voltadas à proteção contra estresse ambiental e fotoinduzido.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('133b4a86-e8b0-4381-a2dc-d3cb52d2213e', 'Glutathione', 'glutathione', 'Glutathione é o tripeptídeo γ-glutamil-cisteinil-glicina, presente em sistemas biológicos nas formas reduzida e oxidada. O grupo tiol da cisteína participa de reações de oxirredução, tornando o ingrediente relevante para projetos cosméticos que buscam suporte antioxidante e proteção contra espécies reativas.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('82ce33e8-a733-49ca-b4b2-31c5029f8cd8', 'Repigard-II', 'repigard-ii', 'Repigard-II é a Ceramide NS/NG da READLINE, um lipídio estrutural relacionado às ceramidas presentes em barreiras biológicas. Em cuidados capilares, ceramidas são utilizadas para complementar a matriz lipídica da cutícula e apoiar formulações destinadas a fios danificados, porosos ou submetidos a processos químicos e térmicos.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('edcb7424-457c-4235-92a7-200decb54734', 'Repigard-IIIB', 'repigard-iiib', 'Repigard-IIIB é a Ceramide NP da READLINE. Ceramidas são componentes fundamentais da organização lipídica do estrato córneo e também podem ser empregadas em sistemas de cuidado capilar, nos quais contribuem para estratégias de reposição de lipídios e melhoria da condição superficial.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('f739f13b-ff66-4192-b577-bcd618c2fe4d', 'NAD+ (Cosméticos)', 'nad-cosmeticos', 'NAD+ é a forma oxidada da nicotinamida adenina dinucleotídeo, coenzima essencial em reações de oxirredução e no metabolismo energético. Também participa como substrato de enzimas relacionadas a sinalização e reparo celular, o que fundamenta seu interesse em pesquisa de cosméticos orientados à longevidade e à resiliência da pele.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('1fca4151-8d07-4c6c-9fb3-ae4777c148a0', 'Lipoid PG 18:0/18:0 (DSPG-Na)', 'lipoid-pg-180180-dspg-na', 'Lipoid PG 18:0/18:0 (DSPG-Na) corresponde a 1,2-distearoil-sn-glicero-3-fosfoglicerol, sal de sódio.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('9b243046-173e-4c3b-9209-4b40d749133b', 'SLM 2026', 'slm-2026', 'SLM 2026 integra a família “Lamellar Bases”. Sua identidade técnica é base com fosfatidilcolina hidrogenada e lipídios idênticos aos do estrato córneo. Essa definição permite selecionar a matéria- prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('3e47c1b1-1353-43cd-8936-176e44d90a55', 'Lipoid PG 18:1/18:1 (DOPG-Na)', 'lipoid-pg-181181-dopg-na', 'Lipoid PG 18:1/18:1 (DOPG-Na) corresponde a 1,2-dioleoil-sn-glicero-3-fosfoglicerol, sal de sódio.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('497ee01c-eeb9-4728-becc-14c3e56368ca', 'Lipoid PE 14:0/14:0 (DMPE)', 'lipoid-pe-140140-dmpe', 'Lipoid PE 14:0/14:0 (DMPE) corresponde a 1,2-dimiristoil-sn-glicero-3-fosfoetanolamina. Trata-se de um fosfolipídio do tipo fosfatidiletanolamina zwitteriônica de cabeça polar compacta, com composição molecular definida, característica que permite controlar de forma mais reprodutível a organização, a carga superficial e as propriedades da fase lipídica.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('42fb6c42-108e-430c-bdd8-64a4d104e3b8', 'Lipoid PE 16:0/16:0 (DPPE)', 'lipoid-pe-160160-dppe', 'Lipoid PE 16:0/16:0 (DPPE) corresponde a 1,2-dipalmitoil-sn-glicero-3-fosfoetanolamina. Trata-se de um fosfolipídio do tipo fosfatidiletanolamina zwitteriônica de cabeça polar compacta, com composição molecular definida, característica que permite controlar de forma mais reprodutível a organização, a carga superficial e as propriedades da fase lipídica.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('55da7ac8-6339-482f-9ace-56fd0a2d1fdc', 'Lipoid PE 18:0/18:0 (DSPE)', 'lipoid-pe-180180-dspe', 'Lipoid PE 18:0/18:0 (DSPE) corresponde a 1,2-distearoil-sn-glicero-3-fosfoetanolamina. Trata-se de um fosfolipídio do tipo fosfatidiletanolamina zwitteriônica de cabeça polar compacta, com composição molecular definida, característica que permite controlar de forma mais reprodutível a organização, a carga superficial e as propriedades da fase lipídica.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('cca7c5c4-12a6-4e1f-96ba-63079d974fd3', 'LIPOID PE 18:0/18:0 - PEG 2000 RS', 'lipoid-pe-180180-peg-2000-rs', 'LIPOID PE 18:0/18:0 - PEG 2000 RS é um padrão de referência qualificado associado ao analito LIPOID PE 18:0/18:0 - PEG 2000. Sua finalidade é fornecer um material rastreável para métodos de identificação, teor, pureza e perfil de componentes em matérias-primas e produtos que contenham fosfolipídios.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('7d398364-9fac-454e-a0f1-36e504ac8cc5', 'Lipoid E 80', 'lipoid-e-80', 'Lipoid E 80 integra a família “Egg Lecithins and Phospholipids”. Sua identidade técnica é fosfolipídios de gema de ovo com 80% de fosfatidilcolina. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('8c55217f-d762-4ef9-8fdd-7e2fa03df1ff', 'SLM Eco', 'slm-eco', 'SLM Eco integra a família “Lamellar Bases”. Sua identidade técnica é base com fosfatidilcolina hidrogenada não transgênica e lipídios idênticos aos do estrato córneo. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('74e87844-cdfc-4aae-9474-18a18558f2f2', 'Phytocodine', 'phytocodine', 'PhytoCodine é um ativo cosmético baseado em peptídeos vegetais, desenvolvido para atuar como sistema de sinalização em projetos voltados à estrutura e à aparência da pele. Seu posicionamento técnico está relacionado à comunicação celular e ao suporte de componentes da matriz extracelular.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('3befde6e-083e-4d83-8311-0ae0789ce3f3', 'PhytoSolve Astaxanthin', 'phytosolve-astaxanthin', 'PhytoSolve Astaxanthin integra a família “Phospholipid Delivery Systems”. Sua identidade técnica é emulsão finamente dispersa com fosfolipídios e astaxantina. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('77247377-fe99-444f-9181-c1b804a0462f', 'PhytoSolve Q10', 'phytosolve-q10', 'PhytoSolve Q10 integra a família “Phospholipid Delivery Systems”. Sua identidade técnica é emulsão finamente dispersa com fosfolipídios e coenzima Q10. Essa definição permite selecionar a matéria- prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('efd4e61e-8710-48ff-aebc-020a6ff88a8a', 'Natipide II', 'natipide-ii', 'Natipide II integra a família “Pre-liposomes”. Sua identidade técnica é pré-lipossomas vazios de fosfolipídios de soja. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('54181353-e624-4571-b1dd-6009f224559e', 'Liposome Basic', 'liposome-basic', 'Liposome Basic integra a família “Pre-liposomes”. Sua identidade técnica é pré-lipossomas com fosfolipídios em glicerina. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('b579494b-35b3-40de-9990-a80a5cc0299b', 'Liposome C Eco', 'liposome-c-eco', 'Liposome C Eco integra a família “Liposome Dispersions”. Sua identidade técnica é dispersão lipossomal de fosfolipídios de soja com ascorbil-2-glicosídeo. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('a4d1f560-080d-45e6-8dfa-2c0ba73ff322', 'Natipide Eco', 'natipide-eco', 'Natipide Eco integra a família “Pre-liposomes”. Sua identidade técnica é pré-lipossomas vazios com lecitina de soja não transgênica. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('c8f51cf3-2228-4c28-ba56-ac700805143a', 'LIPOID PG 18:0/18:0 RS - DSPG-Na', 'lipoid-pg-180180-rs-dspg-na', 'LIPOID PG 18:0/18:0 RS - DSPG-Na é um padrão de referência qualificado associado ao analito LIPOID PG 18:0/18:0 - DSPG-Na. Sua finalidade é fornecer um material rastreável para métodos de identificação, teor, pureza e perfil de componentes em matérias-primas e produtos que contenham fosfolipídios.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('1199f60a-b6d8-4183-9b34-b623bf0ed12a', 'LIPOID PG 18:0/0 RS - LSPG-Na', 'lipoid-pg-1800-rs-lspg-na', 'LIPOID PG 18:0/0 RS - LSPG-Na é um padrão de referência qualificado associado ao analito LIPOID PG 18:0/0 - LSPG-Na. Sua finalidade é fornecer um material rastreável para métodos de identificação, teor, pureza e perfil de componentes em matérias-primas e produtos que contenham fosfolipídios.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('3d3d2fe8-9f31-4d58-a7bb-fe05e4a4a713', 'LIPOID PC 16:0/0 RS - LPPC', 'lipoid-pc-1600-rs-lppc', 'LIPOID PC 16:0/0 RS - LPPC é um padrão de referência qualificado associado ao analito LIPOID PC 16:0/0 - LPPC. Sua finalidade é fornecer um material rastreável para métodos de identificação, teor, pureza e perfil de componentes em matérias-primas e produtos que contenham fosfolipídios.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('93883db8-fb19-4664-b774-d6178b99cc4d', 'LIPOID PC 18:0/0 RS - LSPC', 'lipoid-pc-1800-rs-lspc', 'LIPOID PC 18:0/0 RS - LSPC é um padrão de referência qualificado associado ao analito LIPOID PC 18:0/0 - LSPC. Sua finalidade é fornecer um material rastreável para métodos de identificação, teor, pureza e perfil de componentes em matérias-primas e produtos que contenham fosfolipídios.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('5abd21a4-41a2-45fb-80bc-de0e81bbaffd', 'LIPOID PE 18:0/0-PEG 2000 RS', 'lipoid-pe-1800-peg-2000-rs', 'LIPOID PE 18:0/0-PEG 2000 RS é um padrão de referência qualificado associado ao analito LIPOID PE 18:0/0-PEG 2000. Sua finalidade é fornecer um material rastreável para métodos de identificação, teor, pureza e perfil de componentes em matérias-primas e produtos que contenham fosfolipídios.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('ec478c03-58ad-42d0-a2bf-0362258f36e4', 'Lipoid PE 18:0/18:0 - PEG 2000', 'lipoid-pe-180180-peg-2000', 'Lipoid PE 18:0/18:0 - PEG 2000 integra a família “PEGylated Phospholipids”. Sua identidade técnica é dSPE-PEG 2000: fosfatidiletanolamina distearoilada conjugada a PEG 2000. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('8b3bbf01-42a5-432f-b87e-6ea13d64dd01', 'Lipoid PE 18:1/18:1 (DOPE)', 'lipoid-pe-181181-dope', 'Lipoid PE 18:1/18:1 (DOPE) corresponde a 1,2-dioleoil-sn-glicero-3-fosfoetanolamina. Trata-se de um fosfolipídio do tipo fosfatidiletanolamina zwitteriônica de cabeça polar compacta, com composição molecular definida, característica que permite controlar de forma mais reprodutível a organização, a carga superficial e as propriedades da fase lipídica.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('1d76dba4-e991-4020-922d-76be3e2dc0b9', 'Lipoid PA 16:0/16:0 (DPPA-Na)', 'lipoid-pa-160160-dppa-na', 'Lipoid PA 16:0/16:0 (DPPA-Na) corresponde a 1,2-dipalmitoil-sn-glicero-3-fosfato, sal monossódico.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('d7b3876d-1125-427b-a8a0-f0eb24ce706e', 'Lipoid PA 18:0/18:0 (DSPA-Na)', 'lipoid-pa-180180-dspa-na', 'Lipoid PA 18:0/18:0 (DSPA-Na) corresponde a 1,2-distearoil-sn-glicero-3-fosfato, sal de sódio. Trata-se de um fosfolipídio do tipo ácido fosfatídico aniônico, com composição molecular definida, característica que permite controlar de forma mais reprodutível a organização, a carga superficial e as propriedades da fase lipídica.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('86800a3e-0ac1-4832-aa7a-ecf796394c7f', 'LIPOID PS 18:1/18:1 (DOPS-NA)', 'lipoid-ps-181181-dops-na', 'LIPOID PS 18:1/18:1 (DOPS-NA) corresponde a 1,2-dioleoil-sn-glicero-3-fosfo-L-serina, sal de sódio.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('40e06242-498a-4b28-ad88-c0734e32b518', 'Lipoid S PC RS', 'lipoid-s-pc-rs', 'Lipoid S PC RS é um padrão de referência qualificado associado ao analito Lipoid S PC. Sua finalidade é fornecer um material rastreável para métodos de identificação, teor, pureza e perfil de componentes em matérias-primas e produtos que contenham fosfolipídios.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('628c54df-b715-417c-9d8d-686d114f2cab', 'Lipoid S LPC RS', 'lipoid-s-lpc-rs', 'Lipoid S LPC RS é um padrão de referência qualificado associado ao analito Lipoid S LPC. Sua finalidade é fornecer um material rastreável para métodos de identificação, teor, pureza e perfil de componentes em matérias-primas e produtos que contenham fosfolipídios.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('cb445f4f-9174-4b13-92d3-7c51e34061fc', 'LIPOID S PC-3 RS', 'lipoid-s-pc-3-rs', 'LIPOID S PC-3 RS é um padrão de referência qualificado associado ao analito LIPOID S PC-3. Sua finalidade é fornecer um material rastreável para métodos de identificação, teor, pureza e perfil de componentes em matérias-primas e produtos que contenham fosfolipídios.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('804cd87f-efdd-4fc6-8a83-25324ef4bd75', 'Mulberry Pro', 'mulberry-pro', 'Mulberry Pro é um extrato aquoso-glicerinado de folhas de amoreira-negra, pertencente à linha Herbasol® Pro. A apresentação reúne a matéria-prima botânica em um veículo polar e foi desenvolvida com eficácia avaliada para aplicações de cuidado calmante.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('6ea3596e-80c9-4896-9526-3a4b2826c3b2', 'Ultraspheres 8022 (Retinol)', 'ultraspheres-8022-retinol', 'Ultraspheres 8022 (Retinol) é uma apresentação de retinol em sistema finamente disperso. A pré- dispersão facilita a distribuição do ativo e pode reduzir dificuldades de incorporação associadas à sua lipofilicidade, desde que a concentração e a composição exatas sejam confirmadas na documentação comercial.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('39bbf755-0510-41b1-b2bc-6e6c53ff6084', 'Ultraspheres ACE', 'ultraspheres-ace', 'Ultraspheres ACE integra a família “Fine Dispersions”. Sua identidade técnica é emulsão finamente dispersa com vitaminas A, C e E e fosfatidilcolina de soja. Essa definição permite selecionar a matéria- prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('f89b2c7f-6a40-4bc0-84ea-4c562c514094', 'Citrolumine 8', 'citrolumine-8', 'Citrolumine 8 integra a família “Cosmetic Actives”. Sua identidade técnica é citroflavonoides concentrados e encapsulados em lipossomas. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('64a3c934-6763-47a4-b088-798e48044e12', 'Vitamin F', 'vitamin-f', 'Vitamin F integra a família “Natural Additives”. Sua identidade técnica é mistura de ácidos graxos essenciais poli-insaturados, tradicionalmente denominada vitamina F. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('6191f513-05a4-4863-9291-651db9a6dcf4', 'Natural AHA Complex Liquid', 'natural-aha-complex-liquid', 'Natural AHA Complex Liquid integra a família “Natural Additives”. Sua identidade técnica é combinação líquida e hidrossolúvel de ácidos cítrico, tartárico e lático. Essa definição permite selecionar a matéria- prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('c5a04aee-d92c-422d-a07b-b5ca8488f474', 'Alpha Hydroxy Acids AHA', 'alpha-hydroxy-acids-aha', 'Alpha Hydroxy Acids AHA é uma preparação da categoria de alfa-hidroxiácidos. A planilha não informa a composição individual ou a concentração dos ácidos nesta apresentação; esses dados são essenciais para calcular o teor de ácido livre e definir a segurança do produto final.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('03ba4961-7d2a-4b67-8ce6-4e9b966f1965', 'usNeo', 'usneo', 'usNeo integra a família “Cosmetic Actives”. Sua identidade técnica é extrato de Usnea barbata em propanodiol, sem conservantes adicionados. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('38e30174-3c3e-4b2e-91e1-b849c0aee765', 'Hydro-Gain', 'hydro-gain', 'Hydro-Gain integra a família “Cosmetic Actives”. Sua identidade técnica é sistema hidratante natural com extratos lipofílicos de bétula, óleo de figo-da-índia e lecitina hidrogenada. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('49ddad72-1d7e-4171-82de-7f29dd22b1a7', 'Collagen Stimulation Factor MAP', 'collagen-stimulation-factor-map', 'Collagen Stimulation Factor MAP é um ativo do portfólio cosmético direcionado a estratégias de suporte à síntese e à organização do colágeno. A planilha não apresenta a composição INCI ou o mecanismo detalhado, portanto a identidade completa deve ser confirmada na documentação técnica do produto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('965f5268-bd5d-466d-a60d-9109ea21bb13', 'Depigmentation Factor 2U', 'depigmentation-factor-2u', 'Depigmentation Factor 2U é um ativo cosmético voltado a projetos de luminosidade e redução da aparência de hiperpigmentações. A planilha não informa sua composição INCI nem a via bioquímica específica, por isso o posicionamento final deve ser construído a partir da ficha técnica e dos estudos vigentes.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('6e26035a-d924-4e43-8913-7890787cb665', 'Wheat Herbaprotein™', 'wheat-herbaprotein', 'Wheat Herbaprotein™ integra a família “Natural Additives”. Sua identidade técnica é preparação cosmética baseada em proteínas de trigo hidrolisadas. Essa definição permite selecionar a matéria- prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('da192a14-9353-46c3-8d1a-6682eb10c753', 'Yogurtolin', 'yogurtolin', 'Yogurtolin é uma preparação cosmética associada a componentes de iogurte. Esses materiais fornecem aminoácidos e peptídeos que podem contribuir para formação de filme, retenção de água e melhoria do sensorial em produtos para pele e cabelos.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('dc75337b-c85a-4de4-b02e-2fd63dd60ae4', 'Yoghurt Protein COS GBU', 'yoghurt-protein-cos-gbu', 'Yoghurt Protein COS GBU é uma preparação aquosa-glicerinada de proteína de iogurte ou leite hidrolisada. Esses materiais fornecem aminoácidos e peptídeos que podem contribuir para formação de filme, retenção de água e melhoria do sensorial em produtos para pele e cabelos.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('b69e8475-5b51-491e-87a2-ece12707afdd', 'Lacto Pro™', 'lacto-pro', 'Lacto Pro™ é uma ingrediente funcional de origem láctea para condicionamento e hidratação. Esses materiais fornecem aminoácidos e peptídeos que podem contribuir para formação de filme, retenção de água e melhoria do sensorial em produtos para pele e cabelos.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('3989fc4a-0e26-4ef2-a388-e176d9924747', 'Natural Abrasive Blend Standard', 'natural-abrasive-blend-standard', 'Natural Abrasive Blend Standard é um abrasivo cosmético baseado em partículas naturais, com graduação padrão. Sua função é promover remoção mecânica de material superficial quando as partículas são friccionadas sobre a pele ou integradas a produtos de limpeza e polimento.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('4d76af3b-d19d-4c99-ab43-ce18b10d0671', 'Natural Abrasive Coarse', 'natural-abrasive-coarse', 'Natural Abrasive Coarse é um abrasivo cosmético baseado em partículas naturais, com graduação grossa. Sua função é promover remoção mecânica de material superficial quando as partículas são friccionadas sobre a pele ou integradas a produtos de limpeza e polimento.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('665e1d8d-c59e-43dd-980f-72f44c2d46a2', 'Natural Abrasive Blend Medium-Fine', 'natural-abrasive-blend-medium-fine', 'Natural Abrasive Blend Medium-Fine é um abrasivo cosmético baseado em partículas naturais, com graduação média-fina. Sua função é promover remoção mecânica de material superficial quando as partículas são friccionadas sobre a pele ou integradas a produtos de limpeza e polimento.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('ff709ad6-bbb5-4047-ac67-3489ea6d95e2', 'Bamboo Abrasive GBU', 'bamboo-abrasive-gbu', 'Bamboo Abrasive GBU é um abrasivo cosmético baseado em partículas de bambu, com graduação padrão. Sua função é promover remoção mecânica de material superficial quando as partículas são friccionadas sobre a pele ou integradas a produtos de limpeza e polimento.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('f789fabc-5ceb-496c-8d41-e03e3483a199', 'Argan Oil Herbasol® Extract IPM', 'argan-oil-herbasol-extract-ipm', 'Argan Oil Herbasol® Extract IPM integra a família “Lipophilic Botanical Extracts”. Sua identidade técnica é extrato lipofílico de argan em miristato de isopropila. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('64860c9e-7a27-413c-9ed6-f53f7d622d50', 'Tagua Abrasive', 'tagua-abrasive', 'Tagua Abrasive é um abrasivo cosmético baseado em partículas de tagua, com graduação padrão.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('17e458d1-7628-4d86-a8ed-e2ebb0d459c4', 'Herbaprotect NOX', 'herbaprotect-nox', 'Herbaprotect NOX integra a família “Cosmetic Actives”. Sua identidade técnica é concentrado de flor de romã, folha de perilla e ameixa-kakadu em glicerina. Essa definição permite selecionar a matéria- prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('02d56a1b-f81b-4f70-8e01-665b4c4d52d4', 'Matico Pro', 'matico-pro', 'Matico Pro integra a família “Substantiated Botanical Extracts”. Sua identidade técnica é extrato aquoso-glicerinado de folhas de matico com eficácia avaliada para regeneração. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('c180063e-1849-4735-8ddb-3265df42f80c', 'Herbashield URB', 'herbashield-urb', 'Herbashield URB integra a família “Cosmetic Actives”. Sua identidade técnica é sistema de agrião, cavalinha e urtiga em matriz de fosfolipídios e maltodextrina. Essa definição permite selecionar a matéria-prima com origem, composição e função tecnológica alinhadas ao projeto.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('a7987543-f6e5-4f11-9efb-83d1ae596abf', 'Jackfruit Pro', 'jackfruit-pro', 'Jackfruit Pro é um extrato aquoso-glicerinado de fruto de jaca orgânica, integrante da linha Herbasol® Pro.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('980c4458-4bf9-4045-a842-d57d80d98b12', 'HerbaGlow® NRG', 'herbaglow-nrg', 'HerbaGlow® NRG combina extratos de botões de alcaparra, folhas de amoreira-negra e raiz de rhodiola em uma base de propanodiol, sem conservante adicionado. É um ativo hidrossolúvel desenvolvido para formulações orientadas à energia e à radiância da pele.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('9dfa5e97-69a6-4867-983b-a5d7b201bedc', 'Aloe organic Herbasol® Extract PG unpreserved', 'aloe-organic-herbasol-extract-pg-unpreserved', 'Aloe organic Herbasol® Extract PG unpreserved é um extrato botânico líquido de aloe vera em propilenoglicol e água, sem conservante adicionado. A apresentação polar favorece sua avaliação em sistemas aquosos e emulsões, mantendo definida a identidade do extrato e do veículo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('8c8c9d96-9c5f-4fa6-9ccf-92d1789677a9', 'PhytoCollagen', 'phytocollagen', 'PhytoCollagen é uma preparação aquoso-glicerinada de biopolímeros obtidos da goma de acácia orgânica.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('e8bf0ab7-ecd7-455c-a510-e65adcfd11ed', 'Aloe (Barbadensis)/ Almond Oil Herbamilk® Eco', 'aloe-barbadensis-almond-oil-herbamilk-eco', 'Aloe (Barbadensis)/ Almond Oil Herbamilk® Eco é um leite cosmético vegetal que reúne uma preparação aquosa de aloe vera orgânica e óleo de amêndoas em uma combinação botânico-fosfolipídica. A matriz é fornecida em forma hidrossolúvel e sem conservante adicionado.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('659f591e-cfd7-4b77-8997-82cab16c36b0', 'Amaretine', 'amaretine', 'Amaretine combina andrographolide de folhas de Andrographis paniculata e ácido glicirretínico derivado de alcaçuz em um sistema carreador lipossomal. A preparação é hidrossolúvel, baseada em propilenoglicol e direcionada ao conforto de peles sensíveis.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('728df1d2-4122-4176-a06f-4c5d217303bf', 'BakuLipid', 'bakulipid', 'BakuLipid é uma combinação de bakuchiol de origem vegetal e fosfolipídios insaturados em triglicerídeos de cadeia média. A preparação é lipossolúvel e foi desenvolvida para ampliar a entrega cutânea do bakuchiol em formulações voltadas à aparência jovem e ao controle de oleosidade.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('fa95ede0-7b81-44d9-b3d8-e940be1905b7', 'Immortelle Oil Pro', 'immortelle-oil-pro', 'Immortelle Oil Pro é um extrato de flores orgânicas de immortelle em triglicerídeos de cadeia média.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('5d4f9a7d-efa7-40bc-b341-66ebd9bb90f8', 'Cosmepearl® N', 'cosmepearl-n', 'Cosmepearl® N é um pó fino de pérola recoberto com óleo de jojoba. Trata-se de um ingrediente não solúvel, destinado a formulações em que partículas minerais naturais contribuam para aparência, textura e posicionamento sensorial.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('07138ee1-53b8-461a-8181-60717e94aac5', 'Carotolino', 'carotolino', 'Carotolino é uma composição estabilizada de extrato de raiz de cenoura, óleo de semente de cenoura e beta-caroteno em óleo de canola. É um ativo lipossolúvel, sem conservante adicionado, desenvolvido para aplicações de luminosidade e proteção frente à luz.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('44a7c924-01f7-48f1-92a2-140136196501', 'Anti-Irritant Complex', 'anti-irritant-complex', 'Anti-Irritant Complex reúne extrato de flores de camomila orgânica em propilenoglicol, bisabolol e pantenol.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('a4d574d9-932c-4d20-8220-8dc10904f2c5', 'Aloe (Barbadensis) Herbasol® Extract IPM', 'aloe-barbadensis-herbasol-extract-ipm', 'Aloe (Barbadensis) Herbasol® Extract IPM é um extrato botânico apresentado em miristato de isopropila, um veículo lipofílico. A forma comercial é indicada para projetos em que os constituintes extraídos e o sistema de incorporação devem permanecer compatíveis com a fase oleosa.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('234e7c1c-413f-4292-8592-446055721650', 'Arnica Montana Herbasol® Extract PG (PF)', 'arnica-montana-herbasol-extract-pg-pf', 'Arnica Montana Herbasol® Extract PG (PF) é um extrato botânico líquido de arnica-montana em propilenoglicol e água, sem conservante adicionado. A apresentação polar favorece sua avaliação em sistemas aquosos e emulsões, mantendo definida a identidade do extrato e do veículo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('e9d851a0-0dbf-4402-b508-a9b802b7c5c9', 'Ginkgo Herbasol® Extract PG (PF)', 'ginkgo-herbasol-extract-pg-pf', 'Ginkgo Herbasol® Extract PG (PF) é um extrato botânico líquido de ginkgo em propilenoglicol e água, sem conservante adicionado. A apresentação polar favorece sua avaliação em sistemas aquosos e emulsões, mantendo definida a identidade do extrato e do veículo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('b1bf8dc2-c05b-4c02-8f64-996d3cc695a6', 'Balm Mint Herbasol® Extract PG (PF)', 'balm-mint-herbasol-extract-pg-pf', 'Balm Mint Herbasol® Extract PG (PF) é um extrato botânico líquido de melissa em propilenoglicol e água, sem conservante adicionado. A apresentação polar favorece sua avaliação em sistemas aquosos e emulsões, mantendo definida a identidade do extrato e do veículo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('da3bc31d-ac16-4d03-b3fb-2ba89ff19092', 'Sebostat MPE Herbasec®', 'sebostat-mpe-herbasec', 'Sebostat MPE Herbasec® é um extrato botânico seco da linha Herbasec®. O formato em pó concentra a matéria-prima vegetal e permite seu uso em formulações nas quais a forma sólida, a dispersibilidade e o controle de água são relevantes.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('ef05e1a5-9d05-447a-80a9-bacbb61effa9', 'Green Tea Herbasol® Extract PG (PF)', 'green-tea-herbasol-extract-pg-pf', 'Green Tea Herbasol® Extract PG (PF) é um extrato botânico líquido de chá verde em propilenoglicol e água, sem conservante adicionado. A apresentação polar favorece sua avaliação em sistemas aquosos e emulsões, mantendo definida a identidade do extrato e do veículo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('b18083a9-c52f-4d5a-adf3-8a7bb0198193', 'Violet Herbasol® Extract PG (PF)', 'violet-herbasol-extract-pg-pf', 'Violet Herbasol® Extract PG (PF) é um extrato botânico líquido de violeta em propilenoglicol e água, sem conservante adicionado. A apresentação polar favorece sua avaliação em sistemas aquosos e emulsões, mantendo definida a identidade do extrato e do veículo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('e7b237d5-1030-455e-ae79-fdd27ef3d215', 'Apple Herbasol Vinegar Extract PF', 'apple-herbasol-vinegar-extract-pf', 'Apple Herbasol Vinegar Extract PF é um extrato botânico líquido obtido em uma matriz de vinagre. Além dos constituintes da matéria-prima indicada no nome, o sistema carrega a acidez e os componentes de fermentação característicos do veículo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('a58ee1c5-9c3c-4b4f-b538-0cd815104593', 'Cotton Herbasol Extract IPM', 'cotton-herbasol-extract-ipm', 'Cotton Herbasol Extract IPM é um extrato botânico apresentado em miristato de isopropila, um veículo lipofílico. A forma comercial é indicada para projetos em que os constituintes extraídos e o sistema de incorporação devem permanecer compatíveis com a fase oleosa.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('32ec15a4-3504-423a-ace4-a4337d0872d8', 'Cherry Blossom Herbasol® Extract Glycerine SB', 'cherry-blossom-herbasol-extract-glycerine-sb', 'Cherry Blossom Herbasol® Extract Glycerine SB é um extrato botânico líquido de flor de cerejeira, apresentado em glicerina e água, em sistema glicerinado. A denominação comercial identifica a matéria- prima e o veículo, permitindo selecionar o ingrediente de acordo com a polaridade e o perfil de processo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('62a5386f-d865-44f9-a229-e9b601d0a79f', 'Apple Water Herbasome', 'apple-water-herbasome', 'Apple Water Herbasome é uma preparação da linha Herbasome, na qual o componente indicado no nome comercial é associado a fosfolipídios em uma forma dispersível em água. Essa arquitetura permite trabalhar o ingrediente em formulações aquosas com uma entrega diferente da matéria-prima livre.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('62728973-c689-4eaa-949f-29cfaf76787d', 'Carrot Water Herbasome', 'carrot-water-herbasome', 'Carrot Water Herbasome é uma preparação da linha Herbasome, na qual o componente indicado no nome comercial é associado a fosfolipídios em uma forma dispersível em água. Essa arquitetura permite trabalhar o ingrediente em formulações aquosas com uma entrega diferente da matéria-prima livre.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('9ca303bf-18ac-4ed5-b3c8-36c95e4d5ba2', 'Vanilla/ Almond Oil Herbamilk® Eco', 'vanilla-almond-oil-herbamilk-eco', 'Vanilla/ Almond Oil Herbamilk® Eco é uma preparação cosmética do tipo Herbamilk® Eco, que combina componentes botânicos e lipídicos em uma matriz dispersível em água. A apresentação foi desenvolvida para levar óleos ou matérias-primas vegetais a formulações leves sem depender de uma fase oleosa convencional ampla.
