INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('72fea6d8-7d4c-470e-8b2b-db70fe746010', 'Mate Pro', 'mate-pro', 'Mate Pro é um extrato aquoso-glicerinado de folhas de mate, integrante da linha Herbasol® Pro. A matéria- prima botânica é disponibilizada em veículo polar para formulações que buscam um ingrediente vegetal com eficácia avaliada e identidade composicional definida.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('efc66520-008c-4637-a0d7-40f1b6db187b', 'Blossom Honey Pro', 'blossom-honey-pro', 'Blossom Honey Pro é um extrato aquoso-glicerinado de mel orgânico de flores de acácia, sem conservante adicionado. Pertence à linha Herbasol® Pro e foi desenvolvido para aplicações relacionadas à retenção de água, nutrição e vitalidade da pele.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('39836f33-6284-4e79-a38b-02f96f72333a', 'Peeling Complex', 'peeling-complex', 'Peeling Complex é uma combinação equilibrada de ácido cítrico, gluconolactona e ácido succínico em forma líquida hidrossolúvel. O sistema reúne um alfa-hidroxiácido, um poli-hidroxiácido e um ácido dicarboxílico para formulações esfoliantes de amplo espectro.
