INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('35aec885-93fb-4530-96db-50bebe1d17a4', 'Ginseng LipoHerbasec', 'ginseng-lipoherbasec', 'Ginseng LipoHerbasec é uma preparação seca que combina extrato de raiz de ginseng com fosfolipídios hidrogenados e maltodextrina. A matriz facilita a dispersão de um componente botânico em formulações cosméticas e associa o extrato a uma arquitetura lipídica.
