INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('2a979d64-d84e-4643-b377-28cd41141c8d', 'Green Coffee Pro', 'green-coffee-pro', 'Green Coffee Pro é um extrato aquoso-glicerinado de sementes orgânicas e de comércio justo de café verde. Integra a linha Herbasol® Pro e foi desenvolvido com eficácia avaliada para aplicações de conforto cutâneo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('71b30fc6-34cc-48a9-9233-ca948a0ab5cb', 'Cotton Oil Herbamilk Eco', 'cotton-oil-herbamilk-eco', 'Cotton Oil Herbamilk Eco é uma preparação cosmética do tipo Herbamilk® Eco, que combina componentes botânicos e lipídicos em uma matriz dispersível em água. A apresentação foi desenvolvida para levar óleos ou matérias-primas vegetais a formulações leves sem depender de uma fase oleosa convencional ampla.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('24e2bcf5-2a3f-443e-9ce4-17cf3552bcac', 'Caffeine Herbasome', 'caffeine-herbasome', 'Caffeine Herbasome é uma apresentação lipossomal de cafeína, desenvolvida para facilitar sua dispersão e entrega em formulações cosméticas. A associação com fosfolipídios diferencia o ingrediente da cafeína livre e exige atenção à estrutura do carreador.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('8ec01d94-fe48-4bce-93e7-81676034d337', 'Bearberry Herbasol® Extract PG (PF)', 'bearberry-herbasol-extract-pg-pf', 'Bearberry Herbasol® Extract PG (PF) é um extrato botânico líquido de uva-ursina em propilenoglicol e água, sem conservante adicionado. A apresentação polar favorece sua avaliação em sistemas aquosos e emulsões, mantendo definida a identidade do extrato e do veículo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('5879767a-a716-4069-a4f3-774739446817', 'Rice Herbasol® Extract PG (PF)', 'rice-herbasol-extract-pg-pf', 'Rice Herbasol® Extract PG (PF) é um extrato botânico líquido de arroz em propilenoglicol e água, sem conservante adicionado. A apresentação polar favorece sua avaliação em sistemas aquosos e emulsões, mantendo definida a identidade do extrato e do veículo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('e31d65e8-00d2-435d-b758-27d0ea26f571', 'Maritime Pine (FR) Herbasol® Eco', 'maritime-pine-fr-herbasol-eco', 'Maritime Pine (FR) Herbasol® Eco integra uma linha de extratos botânicos desenvolvida para projetos cosméticos de posicionamento natural. O nome comercial identifica a origem vegetal e a família de processamento, que devem ser relacionadas à documentação técnica vigente.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('a49fc7e0-1fcb-4711-9ea7-850ccd78c500', 'RICE VNGR+®', 'rice-vngr', 'RICE VNGR+® combina extratos de flor de crisântemo branco e raiz de Polygonum multiflorum em um sistema de extração com vinagre de arroz e glicerina. É um ativo líquido orientado a limpeza, controle de oleosidade e cuidados do couro cabeludo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('cb8b1002-374d-4932-8096-1f5cf9045c79', 'CIDER VNGR+®', 'cider-vngr', 'CIDER VNGR+® reúne extratos de flor de malva e folha de urtiga orgânicas em vinagre de maçã orgânico e glicerina. O sistema líquido foi desenvolvido para aplicações de limpeza, controle de oleosidade e cuidado de cabelos e couro cabeludo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('0fd5ec6b-4ccd-4578-abf7-e93e4343a9b6', 'KALE PRO', 'kale-pro', 'KALE PRO é um extrato aquoso-glicerinado de folhas de couve orgânica, pertencente à linha Herbasol® Pro. A preparação é hidrossolúvel e foi desenvolvida com eficácia avaliada para aplicações de proteção antioxidante e radiância.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('fc261bb1-ef8b-418f-8ff6-effbd5b04ed6', 'Capsicum (Cayenne) Herbasol® Extract IPM', 'capsicum-cayenne-herbasol-extract-ipm', 'Capsicum (Cayenne) Herbasol® Extract IPM é um extrato botânico apresentado em miristato de isopropila, um veículo lipofílico. A forma comercial é indicada para projetos em que os constituintes extraídos e o sistema de incorporação devem permanecer compatíveis com a fase oleosa.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('91d69674-8e16-4235-a41a-586a99647022', 'Cranberry Pro', 'cranberry-pro', 'Cranberry Pro é um extrato aquoso-glicerinado de fruto orgânico de cranberry, integrante da linha Herbasol® Pro. O ingrediente foi desenvolvido para modular a adesão e a formação de biofilmes cutâneos sem atuar como biocida.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('8ce1e156-ae24-4a8d-b239-30529d3a9b69', 'HENNA HERBASEC', 'henna-herbasec', 'HENNA HERBASEC é um extrato botânico seco da linha Herbasec®. O formato em pó concentra a matéria-prima vegetal e permite seu uso em formulações nas quais a forma sólida, a dispersibilidade e o controle de água são relevantes.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('e44924a8-01dc-4baf-8a6d-83ef538d5589', 'Honey Extract PG, unpreserved, system 3', 'honey-extract-pg-unpreserved-system-3', 'Honey Extract PG, unpreserved, system 3 é um extrato botânico líquido de mel em propilenoglicol e água, sem conservante adicionado. A apresentação polar favorece sua avaliação em sistemas aquosos e emulsões, mantendo definida a identidade do extrato e do veículo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('00e5276b-cc4a-414e-833f-eb5caec9e717', 'Chamomile Herbasol® Extract PG (PF)', 'chamomile-herbasol-extract-pg-pf', 'Chamomile Herbasol® Extract PG (PF) é um extrato botânico líquido de camomila em propilenoglicol e água, sem conservante adicionado. A apresentação polar favorece sua avaliação em sistemas aquosos e emulsões, mantendo definida a identidade do extrato e do veículo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('58d44b65-c137-43e4-874e-aac0672f7bd5', 'Rose Flower (Petal) Herbasec®', 'rose-flower-petal-herbasec', 'Rose Flower (Petal) Herbasec® é um extrato botânico seco da linha Herbasec®. O formato em pó concentra a matéria-prima vegetal e permite seu uso em formulações nas quais a forma sólida, a dispersibilidade e o controle de água são relevantes.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('5f896db8-173d-45c0-be5e-81cd71c40704', 'Liquorice Herbasol® Extract PG (PF)', 'liquorice-herbasol-extract-pg-pf', 'Liquorice Herbasol® Extract PG (PF) é um extrato botânico líquido de alcaçuz em propilenoglicol e água, sem conservante adicionado. A apresentação polar favorece sua avaliação em sistemas aquosos e emulsões, mantendo definida a identidade do extrato e do veículo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('dad5c8e5-1f02-4c4a-a51f-6671cf4b65fd', 'China (Peruvian) Bark Herbasol® Extract PG (PF)', 'china-peruvian-bark-herbasol-extract-pg-pf', 'China (Peruvian) Bark Herbasol® Extract PG (PF) é um extrato botânico líquido de casca de quina em propilenoglicol e água, sem conservante adicionado. A apresentação polar favorece sua avaliação em sistemas aquosos e emulsões, mantendo definida a identidade do extrato e do veículo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('e5bb27f7-9d33-4f54-86c7-9dc1f7042090', 'Slimming Factor Karkade (PF)', 'slimming-factor-karkade-pf', 'Slimming Factor Karkade (PF) é um ativo cosmético hidrossolúvel baseado em extrato de flores orgânicas de hibisco, apresentado em sistema aquoso com propilenoglicol. A proposta técnica é direcionada a formulações corporais voltadas à aparência de celulite e ao cuidado do contorno corporal.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('42c12afd-edba-4bce-895a-58b753e1ffab', 'Honey Herbasol® Extract sunflower oil', 'honey-herbasol-extract-sunflower-oil', 'Honey Herbasol® Extract sunflower oil é um extrato botânico apresentado em óleo de girassol, formando uma preparação compatível com fases oleosas. O veículo lipídico permite incorporar os constituintes extraídos da matéria-prima em emulsões e sistemas anidros.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('01241ba1-d78c-4769-b530-e1449ca25077', 'Birch Herbasol® Extract Glycerine SB', 'birch-herbasol-extract-glycerine-sb', 'Birch Herbasol® Extract Glycerine SB é um extrato botânico líquido de bétula, apresentado em glicerina e água, em sistema glicerinado. A denominação comercial identifica a matéria-prima e o veículo, permitindo selecionar o ingrediente de acordo com a polaridade e o perfil de processo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('de7c6363-bdb0-4f07-8bc5-c69570899943', 'Aniseed Herbasol® Extract Glycerine SB', 'aniseed-herbasol-extract-glycerine-sb', 'Aniseed Herbasol® Extract Glycerine SB é um extrato botânico líquido de anis, apresentado em glicerina e água, em sistema glicerinado. A denominação comercial identifica a matéria-prima e o veículo, permitindo selecionar o ingrediente de acordo com a polaridade e o perfil de processo.
