INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('12998c60-5c44-43ad-97ac-5b14f2f7caef', 'Artichoke Herbasol® Extract PG (PF)', 'artichoke-herbasol-extract-pg-pf', 'Artichoke Herbasol® Extract PG (PF) é um extrato botânico líquido de alcachofra em propilenoglicol e água, sem conservante adicionado. A apresentação polar favorece sua avaliação em sistemas aquosos e emulsões, mantendo definida a identidade do extrato e do veículo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('f1007665-f55e-40e7-854b-6d3e59e84abe', 'Chamomile Herbasec', 'chamomile-herbasec', 'Chamomile Herbasec é um extrato botânico seco da linha Herbasec®. O formato em pó concentra a matéria-prima vegetal e permite seu uso em formulações nas quais a forma sólida, a dispersibilidade e o controle de água são relevantes.
