INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('29b32d53-231e-4bee-b2ee-b492029bfa61', 'Black Currant Herbasol® Extract Glycerine SB', 'black-currant-herbasol-extract-glycerine-sb', 'Black Currant Herbasol® Extract Glycerine SB é um extrato botânico líquido de groselha-negra, apresentado em glicerina e água, em sistema glicerinado. A denominação comercial identifica a matéria- prima e o veículo, permitindo selecionar o ingrediente de acordo com a polaridade e o perfil de processo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('29a82b43-54ad-4c36-91da-321118c23469', 'Agave Organic Herbasol® Extract Glycerine SB', 'agave-organic-herbasol-extract-glycerine-sb', 'Agave Organic Herbasol® Extract Glycerine SB é um extrato botânico líquido de agave, apresentado em glicerina e água, em sistema glicerinado. A denominação comercial identifica a matéria-prima e o veículo, permitindo selecionar o ingrediente de acordo com a polaridade e o perfil de processo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('869369de-af81-4f02-b3e0-1bdd0a3c6aea', 'Cocos fruit Herbasol(R) Extract Glycerine', 'cocos-fruit-herbasolr-extract-glycerine', 'Cocos fruit Herbasol(R) Extract Glycerine é um extrato botânico líquido de fruto de coco, apresentado em glicerina e água, em sistema glicerinado. A denominação comercial identifica a matéria-prima e o veículo, permitindo selecionar o ingrediente de acordo com a polaridade e o perfil de processo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('7620d19e-063a-454a-849c-4dede16e9473', 'Moringa Pro', 'moringa-pro', 'Moringa Pro é um extrato aquoso-glicerinado de folhas orgânicas de moringa, hidrossolúvel e pertencente à linha Herbasol® Pro. O ativo foi desenvolvido para aplicações de cuidado calmante, suporte à regeneração e proteção do couro cabeludo e da pele.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('5ad7883b-0f27-4bf6-b5b0-a049cb927e6c', 'Rosemary Herbasol Extract PG unpreserved', 'rosemary-herbasol-extract-pg-unpreserved', 'Rosemary Herbasol Extract PG unpreserved é um extrato botânico líquido de alecrim em propilenoglicol e água, sem conservante adicionado. A apresentação polar favorece sua avaliação em sistemas aquosos e emulsões, mantendo definida a identidade do extrato e do veículo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('58cdd27b-9e0a-4339-be7d-f4c036f08c7a', 'Lemon Herbasol Extract Glycerine SB', 'lemon-herbasol-extract-glycerine-sb', 'Lemon Herbasol Extract Glycerine SB é um extrato botânico líquido de limão, apresentado em glicerina e água, em sistema glicerinado. A denominação comercial identifica a matéria-prima e o veículo, permitindo selecionar o ingrediente de acordo com a polaridade e o perfil de processo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('bc9d682c-d554-4439-a95e-7d2147e50029', 'Blackcurrant Pro', 'blackcurrant-pro', 'Blackcurrant Pro é um extrato aquoso-glicerinado de folhas orgânicas de groselha-negra, hidrossolúvel e integrante da linha Herbasol® Pro. O ingrediente apresenta eficácia avaliada para aplicações calmantes e de suporte ao equilíbrio de peles sensibilizadas.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('026b5232-2f24-43e3-b329-5117131d62ad', 'Moringuard', 'moringuard', 'Moringuard é um ativo aquoso-glicerinado e hidrossolúvel obtido de torta de sementes de moringa reaproveitada, proveniente de fonte rastreável. A preparação é sem conservante adicionado e foi desenvolvida para ajudar a proteger a pele frente a vermelhidão, irritação, estresse oxidativo e comprometimento da barreira.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('6524cc8e-ac03-47ae-9e43-960e9b93889f', 'Mountain Tea Pro', 'mountain-tea-pro', 'Mountain Tea Pro é um extrato aquoso-glicerinado, hidrossolúvel e sem conservante adicionado, obtido da erva orgânica Sideritis scardica. Pertence à linha Herbasol® Pro e foi desenvolvido para formulações associadas à proteção antioxidante, recuperação e bem-estar da pele.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('b21757f2-62a6-4b11-ac9a-a1831af30412', 'Wheat Placenta Cos', 'wheat-placenta-cos', 'Wheat Placenta Cos é um extrato concentrado e fracionado de farelo de trigo, apresentado em sistema aquoso com propilenoglicol. A denominação comercial se refere a um complexo vegetal desenvolvido para oferecer propriedades cosméticas semelhantes às associadas a preparações de placenta, sem indicar material placentário de origem animal.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('3e09671f-ee44-4408-9d96-cb73373d5053', 'Raspberry Herbasol Eco', 'raspberry-herbasol-eco', 'Raspberry Herbasol Eco integra uma linha de extratos botânicos desenvolvida para projetos cosméticos de posicionamento natural. O nome comercial identifica a origem vegetal e a família de processamento, que devem ser relacionadas à documentação técnica vigente.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('9972eae3-5e68-4133-a637-001cde95d1f9', 'Cherry Blossom (FR) Herbasol Eco', 'cherry-blossom-fr-herbasol-eco', 'Cherry Blossom (FR) Herbasol Eco integra uma linha de extratos botânicos desenvolvida para projetos cosméticos de posicionamento natural. O nome comercial identifica a origem vegetal e a família de processamento, que devem ser relacionadas à documentação técnica vigente.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('c54e5750-5377-44ff-9cc3-c1744b14cfab', 'Lavender Herbasol Eco', 'lavender-herbasol-eco', 'Lavender Herbasol Eco integra uma linha de extratos botânicos desenvolvida para projetos cosméticos de posicionamento natural. O nome comercial identifica a origem vegetal e a família de processamento, que devem ser relacionadas à documentação técnica vigente.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('b42170fa-d61d-4eb1-bbf4-3f613eb44075', 'Centella Asiatica (Gotu Kola) Herbasec', 'centella-asiatica-gotu-kola-herbasec', 'Centella Asiatica (Gotu Kola) Herbasec é um extrato botânico seco da linha Herbasec®. O formato em pó concentra a matéria-prima vegetal e permite seu uso em formulações nas quais a forma sólida, a dispersibilidade e o controle de água são relevantes.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('035520e3-dc26-4202-b25e-8831279ac18b', 'Cashew Apple Pro', 'cashew-apple-pro', 'Cashew Apple Pro é um extrato aquoso-glicerinado e hidrossolúvel obtido de pedúnculos orgânicos de caju provenientes de uma cadeia de aproveitamento e comércio justo. A preparação é sem conservante adicionado e integra a linha Herbasol® Pro, com eficácia avaliada para hidratação, firmeza e uniformidade visual da pele.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('47e65ae5-040f-4d41-a41d-2f7416b1922a', 'Water Lily Pro', 'water-lily-pro', 'Water Lily Pro é um extrato aquoso em propilenoglicol obtido da raiz de nenúfar-branco, hidrossolúvel e sem conservante adicionado. Integra a linha Herbasol® Pro e foi desenvolvido para aplicações de cuidado do cabelo e couro cabeludo, incluindo condicionamento, resistência e otimização de volume.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('a27e574b-a465-415a-93ab-6d74d5ef6c8d', 'Açai Herbasol Extract Glycerine SB', 'acai-herbasol-extract-glycerine-sb', 'Açai Herbasol Extract Glycerine SB é um extrato botânico líquido de açaí, apresentado em glicerina e água, em sistema glicerinado. A denominação comercial identifica a matéria-prima e o veículo, permitindo selecionar o ingrediente de acordo com a polaridade e o perfil de processo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('59af2b21-1f8d-4669-9b30-adeebc55363a', 'Vine Leaves Herbasol® Extract PG (PF)', 'vine-leaves-herbasol-extract-pg-pf', 'Vine Leaves Herbasol® Extract PG (PF) é um extrato botânico líquido de folhas de videira em propilenoglicol e água, sem conservante adicionado. A apresentação polar favorece sua avaliação em sistemas aquosos e emulsões, mantendo definida a identidade do extrato e do veículo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('24e125e9-40be-4f84-8a15-f723ba81b1cc', 'Chamomile Herbasol® Extract IPM', 'chamomile-herbasol-extract-ipm', 'Chamomile Herbasol® Extract IPM é um extrato botânico apresentado em miristato de isopropila, um veículo lipofílico. A forma comercial é indicada para projetos em que os constituintes extraídos e o sistema de incorporação devem permanecer compatíveis com a fase oleosa.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('c70a5890-cced-403f-a4a3-d333b73c348c', 'Marigold (Calendula) Herbasol® Extract IPM', 'marigold-calendula-herbasol-extract-ipm', 'Marigold (Calendula) Herbasol® Extract IPM é um extrato botânico apresentado em miristato de isopropila, um veículo lipofílico. A forma comercial é indicada para projetos em que os constituintes extraídos e o sistema de incorporação devem permanecer compatíveis com a fase oleosa.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('27db1c05-19f5-4830-8761-a6321ac6d58e', 'Carrot Herbasol® Ferment', 'carrot-herbasol-ferment', 'Carrot Herbasol® Ferment é uma preparação glicerinada e hidrossolúvel obtida por fermentação de raiz de cenoura. A linha Herbasol® Ferment utiliza materiais vegetais orgânicos e fornece metabólitos derivados da biotransformação, com preservação de origem natural.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('7dfeb3a7-e478-417a-90fe-a3244f3d1009', 'Celery Herbasol® Ferment', 'celery-herbasol-ferment', 'Celery Herbasol® Ferment é uma preparação glicerinada e hidrossolúvel obtida por fermentação de material vegetal de aipo. A linha Herbasol® Ferment utiliza materiais vegetais orgânicos e fornece metabólitos derivados da biotransformação, com preservação de origem natural.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('f19d99d4-38ba-40b4-9e32-9e61ac6c0483', 'Cucumber Herbasol® Ferment', 'cucumber-herbasol-ferment', 'Cucumber Herbasol® Ferment é uma preparação glicerinada e hidrossolúvel obtida por fermentação de fruto de pepino. A linha Herbasol® Ferment utiliza materiais vegetais orgânicos e fornece metabólitos derivados da biotransformação, com preservação de origem natural.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('6977cf47-c76b-40e2-8b38-870551971429', 'Kimchi Herbasol® Ferment', 'kimchi-herbasol-ferment', 'Kimchi Herbasol® Ferment é uma preparação glicerinada e hidrossolúvel obtida por fermentação de folhas de repolho fermentado. A linha Herbasol® Ferment utiliza materiais vegetais orgânicos e fornece metabólitos derivados da biotransformação, com preservação de origem natural.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('5e30faec-1eba-462d-b391-507463f6c788', 'Mallow Herbasol Extract Glyberine SB', 'mallow-herbasol-extract-glyberine-sb', 'Mallow Herbasol Extract Glyberine SB é um extrato botânico líquido de malva, apresentado em glicerina e água, em sistema glicerinado. A denominação comercial identifica a matéria-prima e o veículo, permitindo selecionar o ingrediente de acordo com a polaridade e o perfil de processo.
INSERT INTO public.ingredients (id, name, slug, description, inci, active, "createdAt", "updatedAt", "partnerId", "categoryId", excerpt, cta, views) VALUES ('aeaffd1b-277a-44e8-a347-8447d63e9de9', 'ACACIA COLLAGEN (PF)', 'acacia-collagen-pf', 'ACACIA COLLAGEN (PF) é um ingrediente funcional de origem vegetal baseado em componentes da acácia e apresentado para uso cosmético. Sua função tecnológica está associada à formação de filme e ao condicionamento de pele e cabelo.
