INSERT INTO public.categories (id, name, slug, description, "order", active, "createdAt", "updatedAt") VALUES ('e31bcdee-9c71-4796-864e-621a3bd668bc', 'Processo e escalonamento', 'processo-e-escalonamento', 'Da bancada à produção industrial', 2, true, '2026-07-31 18:09:36.612', '2026-07-31 18:09:36.612') ON CONFLICT DO NOTHING;
INSERT INTO public.content (id, title, slug, excerpt, content, featured, status, author, "createdAt", "updatedAt", "publishedAt", "featuredAlt", "seoDescription", "seoTitle", type, views) VALUES ('562fc594-62e1-4aa3-8680-1bb7dba63291', 'Checklist de escalonamento de sistemas lipossomais', 'checklist-escalonamento-lipossomas', 'O que verificar em cada fase — bancada, piloto e industrial — para que a formulação que funcionou no laboratório continue funcionando na produção.', '<p>A maior parte dos problemas de escalonamento de sistemas lipossomais não aparece no laboratório. Aparece quando o equipamento muda e a energia aplicada à dispersão deixa de ser a mesma — e, com ela, muda a arquitetura das vesículas.</p><p>Este checklist organiza os pontos de verificação em três fases, com os parâmetros que precisam ser registrados em cada uma para que a comparação entre escalas seja possível.</p><h3>O que está dentro</h3><ul><li>Fase bancada: definição da matriz lipídica e critérios de aceitação</li><li>Fase piloto: energia de processo, número de ciclos e reprodutibilidade entre lotes</li><li>Fase industrial: controles em processo e plano de estabilidade</li><li>Parâmetros a registrar em todas as fases para comparação entre escalas</li></ul>', '/uploads/demo-capa-checklist.png', 'PUBLISHED', 'Equipe técnica Lipid', '2026-07-31 18:09:36.612', '2026-07-31 18:09:36.612', '2026-07-29 18:09:36.612', 'Capa do checklist de escalonamento de lipossomas', 'Pontos de verificação em bancada, piloto e industrial para escalonar um sistema lipossomal sem perder as características da vesícula.', 'Checklist de escalonamento de lipossomas | Material técnico', 'DOWNLOAD', 0) ON CONFLICT DO NOTHING;
INSERT INTO public.content (id, title, slug, excerpt, content, featured, status, author, "createdAt", "updatedAt", "publishedAt", "featuredAlt", "seoDescription", "seoTitle", type, views) VALUES ('4c8dc987-b6f5-4b64-bbb3-a24efe28f308', 'Fosfatidilcolina em formulações tópicas: o que muda conforme a origem e a pureza', 'fosfatidilcolina-formulacoes-topicas-origem-pureza', 'Soja, girassol ou ovo, com ou sem hidrogenação: entenda como cada escolha altera a rigidez da membrana, a estabilidade oxidativa e o comportamento do sistema na prateleira.', '<p>A fosfatidilcolina é o fosfolipídio majoritário das lecitinas comerciais e o componente estrutural mais usado em sistemas lipídicos de entrega. Sua molécula é anfifílica: uma cabeça polar de fosfocolina e duas cadeias de ácidos graxos apolares. É essa dupla natureza que faz o fosfolipídio se organizar espontaneamente em bicamadas quando disperso em água — a base de lipossomas, bases lamelares e emulsões estruturadas.</p><p>Na prática de formulação, porém, "fosfatidilcolina" não descreve um material único. Duas matérias-primas com o mesmo nome INCI podem se comportar de forma muito diferente conforme a fonte vegetal, o grau de purificação e o tratamento aplicado às cadeias graxas.</p><h2>Origem: soja, girassol e ovo</h2><p>A origem define o perfil de ácidos graxos, e o perfil de ácidos graxos define quase tudo o que vem depois. Lecitinas de <strong>soja</strong> e <strong>girassol</strong> são ricas em cadeias insaturadas, com destaque para o ácido linoleico. Isso mantém a bicamada fluida em temperatura ambiente, o que favorece a formação de vesículas, mas deixa as cadeias suscetíveis à oxidação.</p><p>A fosfatidilcolina de <strong>ovo</strong> apresenta perfil mais saturado que as vegetais, resultando em membranas um pouco menos fluidas. Já o girassol costuma ser escolhido quando o projeto precisa declarar ausência de soja — uma decisão de rótulo e de mercado, não apenas técnica.</p><h2>Pureza: por que o teor importa</h2><p>Lecitinas comerciais vão de frações com teor moderado de fosfatidilcolina até materiais altamente purificados. Quanto menor a pureza, maior a presença de outros fosfolipídios (fosfatidiletanolamina, fosfatidilinositol, ácido fosfatídico) e de componentes neutros como triglicerídeos.</p><p>Esses acompanhantes não são impureza no sentido pejorativo — em muitas aplicações eles contribuem para emulsificação e para o toque sensorial. Mas quando o objetivo é uma bicamada bem definida, com tamanho de vesícula reprodutível, o teor elevado de fosfatidilcolina reduz variáveis e torna o processo mais previsível de lote para lote.</p><h2>Hidrogenação: rigidez e estabilidade</h2><p>A hidrogenação satura as duplas ligações das cadeias graxas. O efeito direto é elevar a <em>temperatura de transição de fase</em> — o ponto em que a bicamada passa do estado gel, mais ordenado, para o estado fluido.</p><p>Uma fosfatidilcolina hidrogenada forma membranas mais rígidas e menos permeáveis à temperatura ambiente, o que tende a favorecer a retenção do ativo encapsulado. Em contrapartida, o processo de produção precisa operar acima da temperatura de transição para que as vesículas se formem, o que impõe um requisito térmico ao ativo e ao equipamento.</p><p>A saturação também remove os pontos vulneráveis à oxidação, e é por isso que materiais hidrogenados costumam apresentar melhor estabilidade oxidativa ao longo da vida útil.</p><h2>Como traduzir isso em decisão</h2><p>Não existe grau universalmente superior; existe adequação ao projeto. Um sistema que precisa liberar rápido e tem processo a frio pede uma fosfatidilcolina insaturada. Um sistema que precisa segurar o ativo e enfrentar prateleira longa se beneficia de uma matriz mais saturada. E um produto que declara livre de soja restringe a origem antes de qualquer outra consideração.</p><p>O ponto de partida sempre é a mesma pergunta: <strong>o que precisa acontecer com o ativo, e em quanto tempo?</strong> A partir daí, origem, pureza e saturação deixam de ser especificações abstratas e viram consequências de uma decisão de desempenho.</p>', '/uploads/demo-capa-fosfolipidios.png', 'PUBLISHED', 'Equipe técnica Lipid', '2026-07-31 18:09:36.612', '2026-07-31 21:20:20.812', '2026-07-22 18:09:36.612', 'Representação de uma bicamada lipídica em fundo azul escuro', 'Como a fonte (soja, girassol, ovo), o teor de fosfatidilcolina e a hidrogenação mudam a rigidez da membrana e a estabilidade do sistema.', 'Fosfatidilcolina: origem, pureza e hidrogenação na formulação', 'ARTIGO', 1) ON CONFLICT DO NOTHING;
INSERT INTO public.content (id, title, slug, excerpt, content, featured, status, author, "createdAt", "updatedAt", "publishedAt", "featuredAlt", "seoDescription", "seoTitle", type, views) VALUES ('8a4ed232-26a8-4fc4-a1a6-281c718dce6e', 'Lipossomas: por que tamanho e lamelaridade decidem o desempenho', 'lipossomas-tamanho-lamelaridade-desempenho', 'Duas formulações com a mesma composição podem se comportar de formas opostas. A diferença costuma estar na arquitetura da vesícula — e ela é definida pelo processo, não pela matéria-prima.', '<p>Lipossomas são vesículas formadas por uma ou mais bicamadas de fosfolipídios envolvendo um compartimento aquoso. Essa arquitetura permite acomodar, ao mesmo tempo, ativos hidrofílicos no núcleo aquoso e ativos lipofílicos dentro da própria bicamada — o que explica a versatilidade do sistema.</p><p>O que costuma surpreender quem está começando é que a composição sozinha não determina o resultado. Duas dispersões feitas com o mesmo fosfolipídio, na mesma concentração, podem apresentar comportamentos bem diferentes se a arquitetura das vesículas for diferente.</p><h2>Lamelaridade: quantas camadas</h2><p>Vesículas <strong>unilamelares</strong> têm uma única bicamada e um núcleo aquoso proporcionalmente maior. Vesículas <strong>multilamelares</strong> têm várias bicamadas concêntricas, como camadas de cebola, com compartimentos aquosos entre elas.</p><p>A consequência prática é direta: para um ativo hidrofílico, a vesícula unilamelar tende a oferecer melhor aproveitamento do volume interno. Para um ativo lipofílico, que se aloja na própria bicamada, o maior número de camadas da multilamelar oferece mais espaço de acomodação. A escolha, portanto, começa pela natureza do ativo.</p><h2>Tamanho: distribuição, não média</h2><p>O tamanho das vesículas influencia estabilidade física, aparência da dispersão e comportamento na aplicação. Mas o número que realmente informa não é o diâmetro médio isolado — é a <em>distribuição</em>.</p><p>Uma dispersão com diâmetro médio adequado mas distribuição larga contém populações muito distintas convivendo, e essas populações não envelhecem no mesmo ritmo. É por isso que o índice de polidispersidade acompanha o diâmetro médio em qualquer caracterização séria: ele diz o quanto a média é confiável.</p><h2>O processo é quem define a arquitetura</h2><p>Aqui está o ponto central: lamelaridade e distribuição de tamanho são resultado do <strong>método de produção e da energia aplicada</strong>, não da matéria-prima escolhida.</p><ul><li><strong>Hidratação de filme lipídico</strong> — método clássico de bancada, tende a produzir vesículas multilamelares e distribuição larga.</li><li><strong>Homogeneização a alta pressão e microfluidização</strong> — reduzem tamanho e lamelaridade conforme se aumenta a energia e o número de ciclos; são as rotas usuais quando há intenção de escalonar.</li><li><strong>Extrusão por membrana</strong> — entrega distribuição estreita e controlada, com limitações práticas de vazão em escala industrial.</li><li><strong>Injeção de solvente</strong> — permite operação contínua, mas traz o solvente residual para dentro do escopo regulatório do produto.</li></ul><h2>Estabilidade: o que observar ao longo do tempo</h2><p>Uma dispersão lipossomal é um sistema termodinamicamente instável — ela é <em>cineticamente</em> estabilizada. Com o tempo, os fenômenos esperados são agregação e fusão de vesículas, hidrólise das ligações éster dos fosfolipídios e oxidação das cadeias insaturadas.</p><p>Por isso o acompanhamento de estabilidade de um sistema lipossomal não se resume ao aspecto visual. Diâmetro, polidispersidade, potencial zeta e teor do ativo ao longo do tempo contam uma história que o olho não vê — e é essa história que sustenta a vida útil declarada.</p><h2>Onde começar</h2><p>A sequência que costuma poupar retrabalho é: definir o que o ativo exige, escolher a arquitetura de vesícula compatível com essa exigência, e só então selecionar processo e matéria-prima capazes de entregar aquela arquitetura de forma reprodutível — na escala em que o produto vai ser fabricado, não apenas na bancada.</p>', '/uploads/demo-capa-lipossomas.png', 'PUBLISHED', 'Equipe técnica Lipid', '2026-07-31 18:09:36.612', '2026-07-31 21:35:46.981', '2026-07-27 18:09:36.612', 'Ilustração de vesículas lipossomais em gradiente azul', 'Como lamelaridade e distribuição de tamanho definem o desempenho de um sistema lipossomal — e por que o processo importa mais que a matéria-prima.', 'Lipossomas: tamanho, lamelaridade e escolha de processo', 'ARTIGO', 1) ON CONFLICT DO NOTHING;
INSERT INTO public.content (id, title, slug, excerpt, content, featured, status, author, "createdAt", "updatedAt", "publishedAt", "featuredAlt", "seoDescription", "seoTitle", type, views) VALUES ('e50212f1-f735-468a-abea-a69a053f1df3', 'Guia de seleção de fosfolipídios para formulação', 'guia-selecao-fosfolipidios', 'Um roteiro de decisão em cinco critérios para escolher o fosfolipídio certo antes de começar a bancada — origem, pureza, saturação, veículo e documentação.', '<p>Escolher o fosfolipídio depois de a formulação já estar em andamento costuma custar caro: troca de matéria-prima em fase adiantada muda estabilidade, processo e, com frequência, o dossiê regulatório.</p><p>Este guia organiza a decisão em cinco critérios, na ordem em que eles realmente restringem as opções, com o que observar em cada um e as perguntas que valem ser feitas ao fornecedor antes de pedir amostra.</p><h3>O que está dentro</h3><ul><li>Como origem e perfil de ácidos graxos limitam as opções seguintes</li><li>Quando o teor elevado de fosfatidilcolina compensa o custo</li><li>O que a hidrogenação impõe ao processo</li><li>Compatibilidade com o veículo e com o sistema conservante</li><li>Documentação a solicitar antes da amostra</li></ul>', '/uploads/demo-capa-guia.png', 'PUBLISHED', 'Equipe técnica Lipid', '2026-07-31 18:09:36.612', '2026-07-31 21:51:39.656', '2026-07-18 18:09:36.612', 'Capa do guia de seleção de fosfolipídios', 'Roteiro de decisão em cinco critérios para escolher o fosfolipídio adequado antes de iniciar o desenvolvimento.', 'Guia de seleção de fosfolipídios | Material técnico Lipid', 'DOWNLOAD', 2) ON CONFLICT DO NOTHING;
