INSERT INTO public.content_faqs (id, question, answer, "contentId", "order", "createdAt") VALUES ('6075ea8d-9c37-4f2a-b5a3-5cabf534e533', 'Qual a diferença entre lecitina e fosfatidilcolina?', 'Lecitina é a matéria-prima completa, uma mistura de fosfolipídios e componentes neutros. A fosfatidilcolina é um dos fosfolipídios presentes nessa mistura, geralmente o majoritário. Materiais chamados de fosfatidilcolina de alta pureza são lecitinas que passaram por purificação para concentrar esse componente específico.', '4c8dc987-b6f5-4b64-bbb3-a24efe28f308', 0, '2026-07-31 18:09:36.612') ON CONFLICT DO NOTHING;
INSERT INTO public.content_faqs (id, question, answer, "contentId", "order", "createdAt") VALUES ('d6dfe8a1-0ee1-4fc5-aec2-8d2294020878', 'Fosfolipídio hidrogenado é sempre melhor?', 'Não. A hidrogenação melhora a estabilidade oxidativa e produz membranas mais rígidas, o que ajuda a reter o ativo encapsulado. Em troca, exige que o processo opere acima da temperatura de transição de fase, o que nem sempre é compatível com o ativo ou com o equipamento disponível. A escolha depende do que a formulação precisa entregar.', '4c8dc987-b6f5-4b64-bbb3-a24efe28f308', 1, '2026-07-31 18:09:36.612') ON CONFLICT DO NOTHING;
INSERT INTO public.content_faqs (id, question, answer, "contentId", "order", "createdAt") VALUES ('378974a6-cb53-460b-9430-3479788f363d', 'Fosfatidilcolina de girassol substitui a de soja diretamente?', 'As duas têm perfis de ácidos graxos semelhantes, o que torna a substituição tecnicamente viável em muitos casos. Ainda assim, qualquer troca de matéria-prima exige reavaliar estabilidade e desempenho na formulação específica, além de verificar a documentação regulatória aplicável ao mercado de destino.', '4c8dc987-b6f5-4b64-bbb3-a24efe28f308', 2, '2026-07-31 18:09:36.612') ON CONFLICT DO NOTHING;
INSERT INTO public.content_faqs (id, question, answer, "contentId", "order", "createdAt") VALUES ('aa4b89cc-72d7-4706-b06f-a6abb2f7ecdc', 'Lipossoma e nanopartícula lipídica são a mesma coisa?', 'Não. O lipossoma tem um núcleo aquoso envolvido por bicamadas de fosfolipídios. As nanopartículas lipídicas têm matriz predominantemente lipídica, sem esse compartimento aquoso interno. A diferença estrutural determina que tipo de ativo cada sistema acomoda melhor.', '8a4ed232-26a8-4fc4-a1a6-281c718dce6e', 0, '2026-07-31 18:09:36.612') ON CONFLICT DO NOTHING;
INSERT INTO public.content_faqs (id, question, answer, "contentId", "order", "createdAt") VALUES ('2d6b05aa-fcd6-48f2-b68f-c4fecff50d43', 'Como saber se a dispersão lipossomal está estável?', 'O aspecto visual não basta. O acompanhamento usual combina diâmetro médio, índice de polidispersidade, potencial zeta e teor do ativo ao longo do tempo, nas condições de armazenamento previstas. Variação nesses parâmetros indica agregação, fusão ou degradação antes de qualquer mudança perceptível a olho nu.', '8a4ed232-26a8-4fc4-a1a6-281c718dce6e', 1, '2026-07-31 18:09:36.612') ON CONFLICT DO NOTHING;
INSERT INTO public.content_faqs (id, question, answer, "contentId", "order", "createdAt") VALUES ('d80f20b7-9333-4a43-8b57-52d74f475d85', 'Por que a formulação muda ao sair da bancada para a produção?', 'Porque a arquitetura das vesículas depende da energia aplicada à dispersão, e equipamentos diferentes aplicam energia de formas diferentes. Sem registrar os parâmetros de processo em cada escala, não há como reproduzir a mesma distribuição de tamanho e lamelaridade obtida no laboratório.', '8a4ed232-26a8-4fc4-a1a6-281c718dce6e', 2, '2026-07-31 18:09:36.612') ON CONFLICT DO NOTHING;
INSERT INTO public.content_faqs (id, question, answer, "contentId", "order", "createdAt") VALUES ('5f3d67fe-3d7a-45fa-90f5-908beb781fa7', 'Preciso escolher o fosfolipídio antes de começar a formular?', 'É o recomendável. Trocar a matéria-prima com o desenvolvimento adiantado costuma alterar estabilidade e processo, e pode exigir refazer estudos já concluídos. Definir o critério antes reduz retrabalho.', 'e50212f1-f735-468a-abea-a69a053f1df3', 0, '2026-07-31 18:09:36.612') ON CONFLICT DO NOTHING;
INSERT INTO public.content_faqs (id, question, answer, "contentId", "order", "createdAt") VALUES ('46b92f5c-799c-4828-9b3c-77f4843c8809', 'Que documentação solicitar ao fornecedor?', 'Ficha técnica, especificação, certificado de análise do lote e a documentação regulatória aplicável ao mercado de destino. Esses documentos prevalecem sobre qualquer material de apoio na hora de decidir parâmetros de formulação e alegações.', 'e50212f1-f735-468a-abea-a69a053f1df3', 1, '2026-07-31 18:09:36.612') ON CONFLICT DO NOTHING;
INSERT INTO public.content_faqs (id, question, answer, "contentId", "order", "createdAt") VALUES ('45b057f7-dfb7-42d4-a2d3-165e8a7c6063', 'Em que fase o escalonamento costuma falhar?', 'Com mais frequência na passagem de bancada para piloto, quando o método de dispersão muda. É o momento em que a energia aplicada deixa de ser equivalente e a arquitetura da vesícula se altera, mesmo com a composição idêntica.', '562fc594-62e1-4aa3-8680-1bb7dba63291', 0, '2026-07-31 18:09:36.612') ON CONFLICT DO NOTHING;
INSERT INTO public.content_faqs (id, question, answer, "contentId", "order", "createdAt") VALUES ('a57953ed-5a4a-4cf0-8987-7729de333779', 'O checklist serve para qualquer sistema lipídico?', 'A estrutura de fases e o princípio de registrar parâmetros para comparar escalas valem de forma ampla. Os critérios de aceitação específicos, porém, precisam ser definidos para cada formulação e cada ativo.', '562fc594-62e1-4aa3-8680-1bb7dba63291', 1, '2026-07-31 18:09:36.612') ON CONFLICT DO NOTHING;
